(318387,35377,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... mit Blumen sorry. Respekt.'::text,'sagst'::text,'sagt'::text,'sagend'::text,'Du sagst mit Blumen sorry. Respekt.'::text),
(318391,35377,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... «вибач» із квітами. Респект.'::text,'кажеш'::text,'каже'::text,'кажучи'::text,'Ти кажеш «вибач» із квітами. Респект.'::text),
(318390,35377,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... perdón con flores. Respeto.'::text,'pides'::text,'pide'::text,'pidiendo'::text,'Tú pides perdón con flores. Respeto.'::text),
(318389,35377,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... pardon avec des fleurs. Respect.'::text,'demandes'::text,'demande'::text,'demandant'::text,'Tu demandes pardon avec des fleurs. Respect.'::text),
(318392,35377,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen çiçeklerle özür ... Helal olsun.'::text,'dilersin'::text,'diler'::text,'dileyerek'::text,'Sen çiçeklerle özür dilersin Helal olsun.'::text),
(318393,35377,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te virággal ... bocsánatot. Respekt.'::text,'kérsz'::text,'kér'::text,'kérő'::text,'Te virággal kérsz bocsánatot. Respekt.'::text),
(318423,35381,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es tut ihm leid, weil diese Sauerei ... ist als ein kleiner Tropfen.'::text,'größer'::text,'größer'::text,'am größten'::text,'Es tut ihm leid, weil diese Sauerei größer ist als ein kleiner Tropfen.'::text),
(318427,35381,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він шкодує, бо цей безлад ... за маленьку краплю.'::text,'більший'::text,'більш великий'::text,'найбільший'::text,'Він шкодує, бо цей безлад більший за маленьку краплю.'::text),
(318426,35381,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él lo siente porque este desastre es ... que una gotita.'::text,'más grande'::text,'más grande'::text,'el más grande'::text,'Él lo siente porque este desastre es más grande que una gotita.'::text),
(318425,35381,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est désolé parce que ce bazar est ... qu''une petite goutte.'::text,'plus grand'::text,'plus grand'::text,'le plus grand'::text,'Il est désolé parce que ce bazar est plus grand qu''une petite goutte.'::text),
(318428,35381,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O üzgün çünkü bu dağınıklık küçük bir damladan ...'::text,'daha büyük'::text,'daha büyük'::text,'en büyük'::text,'O üzgün çünkü bu dağınıklık küçük bir damladan daha büyük.'::text),
(318429,35381,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő sajnálja, mert ez a kosz ... egy kis cseppnél.'::text,'nagyobb'::text,'nagyobb'::text,'legnagyobb'::text,'Ő sajnálja, mert ez a kosz nagyobb egy kis cseppnél.'::text),
(309828,34426,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... mit einem Lineal den Plan eines Hauses zeichnen.'::text,'kann'::text,'kann'::text,'kann'::text,'Er kann mit einem Lineal den Plan eines Hauses zeichnen.'::text),
(309832,34426,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... накреслити план будинку за допомогою лінійки.'::text,'може'::text,'може'::text,'може'::text,'Він може накреслити план будинку за допомогою лінійки.'::text),
(309831,34426,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... dibujar el plano de una casa con una regla.'::text,'puede'::text,'puede'::text,'puede'::text,'Él puede dibujar el plano de una casa con una regla.'::text),
(309830,34426,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... dessiner le plan d''une maison avec une règle.'::text,'peut'::text,'peut'::text,'peut'::text,'Il peut dessiner le plan d''une maison avec une règle.'::text),
(309833,34426,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O cetvelle bir evin planını ...'::text,'çizebilir'::text,'çizebilir'::text,'çizebilir'::text,'O cetvelle bir evin planını çizebilir.'::text),
(309834,34426,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... megrajzolni egy ház tervrajzát vonalzóval.'::text,'tudja'::text,'tudja'::text,'tudja'::text,'Ő tudja megrajzolni egy ház tervrajzát vonalzóval.'::text),
(302862,33652,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei ... tanzen in der engen Gasse.'::text,'Personen'::text,'Personen'::text,'Person'::text,'Zwei Personen tanzen in der engen Gasse.'::text),
(302866,33652,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє ... танцюють у вузькому провулку.'::text,'людей'::text,'людей'::text,'людина'::text,'Двоє людей танцюють у вузькому провулку.'::text),
(302865,33652,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dos ... bailan en el callejón estrecho.'::text,'personas'::text,'personas'::text,'persona'::text,'Dos personas bailan en el callejón estrecho.'::text),
(302864,33652,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux ... dansent dans la ruelle étroite.'::text,'personnes'::text,'personnes'::text,'personne'::text,'Deux personnes dansent dans la ruelle étroite.'::text),
(302867,33652,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dar sokakta iki ... dans ediyor.'::text,'kişi'::text,'kişiler'::text,'kişi'::text,'Dar sokakta iki kişi dans ediyor.'::text),
(302868,33652,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két ... táncol a szűk sikátorban.'::text,'ember'::text,'ember'::text,'ember'::text,'Két ember táncol a szűk sikátorban.'::text),
(327999,36445,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Holz ... in der Feuergrube.'::text,'brennt'::text,'brennen'::text,'brennend'::text,'Das Holz brennt in der Feuergrube.'::text),
(328003,36445,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дерево ... у вогнищі.'::text,'горить'::text,'горіти'::text,'горячи'::text,'Дерево горить у вогнищі.'::text),
(328002,36445,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La leña ... en el hoyo del fuego.'::text,'arde'::text,'arder'::text,'ardiendo'::text,'La leña arde en el hoyo del fuego.'::text),
(328001,36445,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bois ... dans le foyer.'::text,'brûle'::text,'brûler'::text,'brûlant'::text,'Le bois brûle dans le foyer.'::text),
(328004,36445,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Odun ateş çukurunda ...'::text,'yanar'::text,'yanmak'::text,'yanarak'::text,'Odun ateş çukurunda yanar.'::text),
(328005,36445,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fa ... a tűzgödörben.'::text,'ég'::text,'égni'::text,'égő'::text,'A fa ég a tűzgödörben.'::text),
(296274,32920,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich lüg nicht, du siehst cool aus mit nur ... Möbelstück.'::text,'einem'::text,'ersten'::text,'einmal'::text,'Ich lüg nicht, du siehst cool aus mit nur einem Möbelstück.'::text),
(296278,32920,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брешу, ти виглядаєш круто лише з ... предметом меблів.'::text,'одним'::text,'першим'::text,'один раз'::text,'Не брешу, ти виглядаєш круто лише з одним предметом меблів.'::text),
(296277,32920,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, tú te ves guay con solo ... mueble.'::text,'un'::text,'primer'::text,'una vez'::text,'No voy a mentir, tú te ves guay con solo un mueble.'::text),
(296276,32920,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, t''as l''air cool avec juste ... meuble.'::text,'un'::text,'premier'::text,'une fois'::text,'Je vais pas mentir, t''as l''air cool avec juste un meuble.'::text),
(296279,32920,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, sen sadece ... mobilyayla çok havalı görünüyorsun.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Yalan yok, sen sadece bir mobilyayla çok havalı görünüyorsun.'::text),
(296280,32920,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, te menőn nézel ki mindössze ... bútorral.'::text,'egy'::text,'első'::text,'egyszer'::text,'Nem hazudok, te menőn nézel ki mindössze egy bútorral.'::text),
(296292,32922,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, ein gemütliches Zimmer: Da ist nicht ... Mobiliar, nur ein kleiner Stuhl.'::text,'viel'::text,'viele'::text,'etwas'::text,'Klar, ein gemütliches Zimmer: Da ist nicht viel Mobiliar, nur ein kleiner Stuhl.'::text),
(296296,32922,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно ж, затишна кімната: тут немає ... меблів, лише один маленький стілець.'::text,'багато'::text,'багато'::text,'трохи'::text,'Звісно ж, затишна кімната: тут немає багато меблів, лише один маленький стілець.'::text),
(296295,32922,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claro, una habitación acogedora: no hay ... mobiliario, solo una sillita.'::text,'mucho'::text,'muchos'::text,'algo de'::text,'Claro, una habitación acogedora: no hay mucho mobiliario, solo una sillita.'::text),
(296294,32922,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment une chambre cosy : il n''y a pas ... meubles, juste une petite chaise.'::text,'beaucoup de'::text,'beaucoup de'::text,'des'::text,'Évidemment une chambre cosy : il n''y a pas beaucoup de meubles, juste une petite chaise.'::text),
(296297,32922,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki rahat bir oda: ... mobilya yok, sadece küçük bir sandalye.'::text,'çok'::text,'çok'::text,'biraz'::text,'Belli ki rahat bir oda: çok mobilya yok, sadece küçük bir sandalye.'::text),
(296298,32922,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván hangulatos szoba: nincs ... bútor, csak egy kis szék.'::text,'sok'::text,'sok'::text,'némi'::text,'Nyilván hangulatos szoba: nincs sok bútor, csak egy kis szék.'::text),
(304653,33851,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Menge schaut dem Marsch zu, und Trommler führen ... Marsch an.'::text,'den'::text,'einen'::text,'einen'::text,'Eine Menge schaut dem Marsch zu, und Trommler führen den Marsch an.'::text),
(304657,33851,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Натовп спостерігає за ходою, а барабанщики очолюють ... ходу.'::text,''::text,NULL::text,NULL::text,'Натовп спостерігає за ходою, а барабанщики очолюють ходу.'::text),
(304656,33851,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una multitud mira el desfile, y los tamborileros encabezan ... desfile.'::text,'el'::text,'un'::text,'un'::text,'Una multitud mira el desfile, y los tamborileros encabezan el desfile.'::text),
(304655,33851,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une foule regarde le défilé, et des tambours mènent ... défilé.'::text,'le'::text,'un'::text,'un'::text,'Une foule regarde le défilé, et des tambours mènent le défilé.'::text),
(304658,33851,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık yürüyüşü izliyor ve davulcular ... yürüyüşe öncülük ediyor.'::text,''::text,'bir'::text,'bir'::text,'Kalabalık yürüyüşü izliyor ve davulcular yürüyüşe öncülük ediyor.'::text),
(304659,33851,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tömeg nézi a felvonulást, és dobosok vezetik ... felvonulást.'::text,'a'::text,'egy'::text,'egy'::text,'Tömeg nézi a felvonulást, és dobosok vezetik a felvonulást.'::text),
(304671,33853,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, so ... Leute klatschen bei diesem Marsch, echt jetzt.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Alter, so viele Leute klatschen bei diesem Marsch, echt jetzt.'::text),
(304675,33853,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, так ... людей плескають на цій ході, чесно.'::text,'багато'::text,'багато'::text,'будь-яких'::text,'Бро, так багато людей плескають на цій ході, чесно.'::text),
(304674,33853,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, hay ... gente aplaudiendo en este desfile, en serio.'::text,'mucha'::text,'mucha'::text,'cualquier'::text,'Tío, hay mucha gente aplaudiendo en este desfile, en serio.'::text),
(304673,33853,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il y a vraiment ... gens qui applaudissent ce défilé, sérieux.'::text,'beaucoup de'::text,'beaucoup de'::text,'n''importe quels'::text,'Frérot, il y a vraiment beaucoup de gens qui applaudissent ce défilé, sérieux.'::text),
(304676,33853,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu yürüyüşte o kadar ... insan alkışlıyor ki, cidden.'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Kanka, bu yürüyüşte o kadar çok insan alkışlıyor ki, cidden.'::text),
(304677,33853,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, olyan ... ember tapsol ezen a felvonuláson, komolyan.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Tesó, olyan sok ember tapsol ezen a felvonuláson, komolyan.'::text),
(309162,34352,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ruft sie an, während sie rennt? Ihren Chef.'::text,'Wen'::text,'Wo'::text,'Wann'::text,'Wen ruft sie an, während sie rennt? Ihren Chef.'::text),
(309166,34352,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона телефонує, поки біжить? Своєму босу.'::text,'Кому'::text,'Де'::text,'Коли'::text,'Кому вона телефонує, поки біжить? Своєму босу.'::text),
(309165,34352,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... llama ella mientras corre? A su jefe.'::text,'A quién'::text,'Dónde'::text,'Cuándo'::text,'¿A quién llama ella mientras corre? A su jefe.'::text),
(309164,34352,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... appelle-t-elle pendant qu''elle court ? Son boss.'::text,'Qui'::text,'Où'::text,'Quand'::text,'Qui appelle-t-elle pendant qu''elle court ? Son boss.'::text),
(309167,34352,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koşarken o ... arıyor? Patronunu.'::text,'kimi'::text,'nerede'::text,'ne zaman'::text,'Koşarken o kimi arıyor? Patronunu.'::text),
(309168,34352,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hív fel ő, miközben fut? A főnökét.'::text,'Kit'::text,'Hol'::text,'Mikor'::text,'Kit hív fel ő, miközben fut? A főnökét.'::text),
(301791,33533,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Kinder schreien vor Freude! Der Lärm ist unglaublich!'::text,'Zwei'::text,'Zweite'::text,'Zweimal'::text,'Zwei Kinder schreien vor Freude! Der Lärm ist unglaublich!'::text),
(301795,33533,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... дітей кричать від радості! Шум неймовірний!'::text,'Двоє'::text,'Другі'::text,'Двічі'::text,'Двоє дітей кричать від радості! Шум неймовірний!'::text),
(301794,33533,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... niños gritan de alegría! ¡El ruido es increíble!'::text,'Dos'::text,'Segundos'::text,'Dos veces'::text,'¡Dos niños gritan de alegría! ¡El ruido es increíble!'::text),
(301793,33533,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... enfants crient de joie ! Le bruit est incroyable !'::text,'Deux'::text,'Deuxièmes'::text,'Deux fois'::text,'Deux enfants crient de joie ! Le bruit est incroyable !'::text),
(301796,33533,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... çocuk sevinçten çığlık atıyor! Gürültü inanılmaz!'::text,'İki'::text,'İkinci'::text,'İki kez'::text,'İki çocuk sevinçten çığlık atıyor! Gürültü inanılmaz!'::text),
(301797,33533,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... gyerek sikít örömében! Hihetetlen a zaj!'::text,'Két'::text,'Második'::text,'Kétszer'::text,'Két gyerek sikít örömében! Hihetetlen a zaj!'::text),
(301809,33535,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat gesagt, die Kinder sind normalerweise ruhig, aber gestern ... sie vor Freude.'::text,'schrien'::text,'schreien'::text,NULL::text,'Hör zu, sie hat gesagt, die Kinder sind normalerweise ruhig, aber gestern schrien sie vor Freude.'::text),
(301813,33535,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона казала, що діти зазвичай спокійні, але вчора вони ... від радості.'::text,'кричали'::text,'кричать'::text,NULL::text,'Слухай, вона казала, що діти зазвичай спокійні, але вчора вони кричали від радості.'::text),
(301812,33535,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ella dijo que los niños suelen estar tranquilos, pero ayer ... de alegría.'::text,'gritaron'::text,'gritan'::text,NULL::text,'Oye, ella dijo que los niños suelen estar tranquilos, pero ayer gritaron de alegría.'::text),
(301811,33535,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle a dit que les enfants sont calmes d''habitude, mais hier ils ... de joie.'::text,'ont crié'::text,'crient'::text,NULL::text,'Écoute, elle a dit que les enfants sont calmes d''habitude, mais hier ils ont crié de joie.'::text),
(301814,33535,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, o çocukların genelde sakin olduğunu söyledi ama dün sevinçten ...'::text,'çığlık attılar'::text,'çığlık atarlar'::text,NULL::text,'Dinle, o çocukların genelde sakin olduğunu söyledi ama dün sevinçten çığlık attılar.'::text),
(301815,33535,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, ő azt mondta, hogy a gyerekek általában nyugodtak, de tegnap ... örömükben.'::text,'sikítottak'::text,'sikítanak'::text,NULL::text,'Figyelj, ő azt mondta, hogy a gyerekek általában nyugodtak, de tegnap sikítottak örömükben.'::text),
(297930,33104,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich sagen die Regeln, dass jeder Rettungsschwimmer eine gelbe Kappe tragen ...'::text,'muss'::text,'muss'::text,'sollte'::text,'Mädel, angeblich sagen die Regeln, dass jeder Rettungsschwimmer eine gelbe Kappe tragen muss.'::text),
(297934,33104,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, за правилами кожен рятувальник ... носити жовту кепку.'::text,'має'::text,'мусить'::text,'мав би'::text,'Подруго, кажуть, за правилами кожен рятувальник має носити жовту кепку.'::text),
(297933,33104,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer las normas dicen que cada socorrista ... llevar una gorra amarilla.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Tía, al parecer las normas dicen que cada socorrista tiene que llevar una gorra amarilla.'::text),
(297932,33104,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment le règlement dit que chaque sauveteur ... porter une casquette jaune.'::text,'doit'::text,'doit'::text,'devrait'::text,'Ma belle, apparemment le règlement dit que chaque sauveteur doit porter une casquette jaune.'::text),
(297935,33104,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya kurallara göre her cankurtaran sarı şapka ...'::text,'takmak zorunda'::text,'takmalı'::text,'takmalı'::text,'Kızım, güya kurallara göre her cankurtaran sarı şapka takmak zorunda.'::text),
(297936,33104,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a szabályok szerint minden vízimentőnek sárga sapkát ... viselnie.'::text,'kell'::text,'kell'::text,'kellene'::text,'Csajszi, állítólag a szabályok szerint minden vízimentőnek sárga sapkát kell viselnie.'::text),
