(325042,36116,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... зробити швидкий поворот на крутому схилі.'::text,'може'::text,'є'::text,'має'::text,'Вона може зробити швидкий поворот на крутому схилі.'::text),
(325041,36116,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... hacer un giro rápido en la pendiente empinada.'::text,'puede'::text,'está'::text,'tiene'::text,'Ella puede hacer un giro rápido en la pendiente empinada.'::text),
(325040,36116,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... faire un virage rapide sur la pente raide.'::text,'peut'::text,'est'::text,'a'::text,'Elle peut faire un virage rapide sur la pente raide.'::text),
(325043,36116,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dik yamaçta hızlı bir dönüş ...'::text,'yapabilir'::text,NULL::text,'var'::text,'O dik yamaçta hızlı bir dönüş yapabilir.'::text),
(325044,36116,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... egy gyors fordulót venni a meredek lejtőn.'::text,'tud'::text,'van'::text,'van neki'::text,'Ő tud egy gyors fordulót venni a meredek lejtőn.'::text),
(302016,33558,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Tritt schleudert die Blätter in die Luft.'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Dieser Tritt schleudert die Blätter in die Luft.'::text),
