(302019,33558,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... patada lanza las hojas al aire.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta patada lanza las hojas al aire.'::text),
(302018,33558,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... coup de pied envoie les feuilles en l''air.'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Ce coup de pied envoie les feuilles en l''air.'::text),
(302021,33558,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tekme yaprakları havaya uçuruyor.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu tekme yaprakları havaya uçuruyor.'::text),
(302022,33558,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a rúgás a levegőbe repíti a leveleket.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a rúgás a levegőbe repíti a leveleket.'::text),
(299343,33261,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist die Tasche so schwer? Töpfe und Pfannen hängen daran.'::text,'Warum'::text,'Wer'::text,'Wann'::text,'Warum ist die Tasche so schwer? Töpfe und Pfannen hängen daran.'::text),
(299347,33261,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... сумка така важка? На ній висять каструлі й сковорідки.'::text,'Чому'::text,'Хто'::text,'Коли'::text,'Чому сумка така важка? На ній висять каструлі й сковорідки.'::text),
(299346,33261,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... es tan pesada la bolsa? Tiene ollas y sartenes colgadas.'::text,'Por qué'::text,'Quién'::text,'Cuándo'::text,'¿Por qué es tan pesada la bolsa? Tiene ollas y sartenes colgadas.'::text),
(299345,33261,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le sac est-il si lourd ? Des casseroles et des poêles y sont accrochées.'::text,'Pourquoi'::text,'Qui'::text,'Quand'::text,'Pourquoi le sac est-il si lourd ? Des casseroles et des poêles y sont accrochées.'::text),
(299348,33261,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çanta ... bu kadar ağır? Üstünde tencere tava asılı.'::text,'neden'::text,'kim'::text,'ne zaman'::text,'Çanta neden bu kadar ağır? Üstünde tencere tava asılı.'::text),
(299349,33261,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ilyen nehéz a táska? Lábasok és serpenyők lógnak rajta.'::text,'Miért'::text,'Ki'::text,'Mikor'::text,'Miért ilyen nehéz a táska? Lábasok és serpenyők lógnak rajta.'::text),
(299370,33264,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unglaublich! Sein Rucksack ist ... als ein Kühlschrank!'::text,'schwerer'::text,'schwerer'::text,'am schwersten'::text,'Unglaublich! Sein Rucksack ist schwerer als ein Kühlschrank!'::text),
(299374,33264,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Неймовірно! Його рюкзак ... за холодильник!'::text,'важчий'::text,'більш важкий'::text,'найважчий'::text,'Неймовірно! Його рюкзак важчий за холодильник!'::text),
(299373,33264,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Increíble! ¡Su mochila es ... que una nevera!'::text,'más pesada'::text,'más pesada'::text,'la más pesada'::text,'¡Increíble! ¡Su mochila es más pesada que una nevera!'::text),
(299372,33264,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Incroyable ! Son sac à dos est ... qu''un frigo !'::text,'plus lourd'::text,'plus lourd'::text,'le plus lourd'::text,'Incroyable ! Son sac à dos est plus lourd qu''un frigo !'::text),
(299375,33264,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnanılmaz! Onun sırt çantası bir buzdolabından ...!'::text,'daha ağır'::text,'daha ağır'::text,'en ağır'::text,'İnanılmaz! Onun sırt çantası bir buzdolabından daha ağır!'::text),
(299376,33264,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hihetetlen! A hátizsákja ... egy hűtőnél!'::text,'nehezebb'::text,'nehezebb'::text,'legnehezebb'::text,'Hihetetlen! A hátizsákja nehezebb egy hűtőnél!'::text),
(295509,32835,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Brot ... so frisch! Das ist absolut unglaublich!'::text,'ist'::text,'sind'::text,'bin'::text,'Das Brot ist so frisch! Das ist absolut unglaublich!'::text),
(295513,32835,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хліб ... такий свіжий! Це просто неймовірно!'::text,'є'::text,'є'::text,'є'::text,'Хліб є такий свіжий! Це просто неймовірно!'::text),
(295512,32835,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El pan ... tan fresco! ¡Esto es absolutamente increíble!'::text,'está'::text,'están'::text,'estoy'::text,'¡El pan está tan fresco! ¡Esto es absolutamente increíble!'::text),
(295511,32835,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pain ... tellement frais ! C''est absolument incroyable !'::text,'est'::text,'sont'::text,'suis'::text,'Le pain est tellement frais ! C''est absolument incroyable !'::text),
