(295545,32839,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie haben einen Plan. Sie ... dem ganzen Dorf frische Kuchen verkaufen.'::text,'werden'::text,'werden'::text,'verkaufen'::text,'Sie haben einen Plan. Sie werden dem ganzen Dorf frische Kuchen verkaufen.'::text),
