(295548,32839,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos tienen un plan. ... pasteles frescos a todo el pueblo.'::text,'Van a vender'::text,'Venderán'::text,'Venden'::text,'Ellos tienen un plan. Van a vender pasteles frescos a todo el pueblo.'::text),
(295547,32839,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont un plan. Ils ... des tartes fraîches à tout le village.'::text,'vont vendre'::text,'vendront'::text,'vendent'::text,'Ils ont un plan. Ils vont vendre des tartes fraîches à tout le village.'::text),
(295550,32839,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir planları var. Onlar bütün köye taze turta ...'::text,'satacaklar'::text,'satacaklar'::text,'satarlar'::text,'Bir planları var. Onlar bütün köye taze turta satacaklar.'::text),
