(321982,35776,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Медсестра намотує стрічку ... його руки.'::text,'навколо'::text,'біля'::text,'у'::text,'Медсестра намотує стрічку навколо його руки.'::text),
