(321980,35776,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''infirmière enroule une bande ... sa main.'::text,'autour de'::text,'à'::text,'dans'::text,'L''infirmière enroule une bande autour de sa main.'::text),
