(296598,32956,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo Bro, ... trefft ihr euch alle? Auf dem Dach, Mann.'::text,'Wo'::text,'Wann'::text,'Wer'::text,'Yo Bro, Wo trefft ihr euch alle? Auf dem Dach, Mann.'::text),
(296602,32956,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, бро, ... ви всі збираєтеся? На даху, чувак.'::text,'Де'::text,'Коли'::text,'Хто'::text,'Йо, бро, Де ви всі збираєтеся? На даху, чувак.'::text),
(296601,32956,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, tío, ¿... os juntáis vosotros? En la azotea, tío.'::text,'Dónde'::text,'Cuándo'::text,'Quién'::text,'Ey, tío, ¿Dónde os juntáis vosotros? En la azotea, tío.'::text),
(296600,32956,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo frérot, ... est-ce que vous vous retrouvez tous ? Sur le toit, mec.'::text,'Où'::text,'Quand'::text,'Qui'::text,'Yo frérot, Où est-ce que vous vous retrouvez tous ? Sur le toit, mec.'::text),
(296603,32956,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, siz ... toplanıyorsunuz? Çatıda, dostum.'::text,'nerede'::text,'ne zaman'::text,'kim'::text,'Kanka, siz nerede toplanıyorsunuz? Çatıda, dostum.'::text),
(296604,32956,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... gyűltök össze ti? A tetőn, haver.'::text,'Hol'::text,'Mikor'::text,'Ki'::text,'Tesó, Hol gyűltök össze ti? A tetőn, haver.'::text),
(296625,32959,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... die Freunde sich bis acht treffen. Bar-Regel.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Mädel, angeblich müssen die Freunde sich bis acht treffen. Bar-Regel.'::text),
(296629,32959,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, друзі ... зібратися до восьмої. Правило бару.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Подруго, кажуть, друзі мають зібратися до восьмої. Правило бару.'::text),
(296628,32959,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer los amigos ... reunirse antes de las ocho. Regla del bar.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Tía, al parecer los amigos tienen que reunirse antes de las ocho. Regla del bar.'::text),
(296627,32959,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment les amis ... se retrouver avant huit heures. Règle du bar.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Ma belle, apparemment les amis doivent se retrouver avant huit heures. Règle du bar.'::text),
(296630,32959,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya barın kuralı: arkadaşlar sekize kadar ...'::text,'toplanmak zorunda'::text,'toplanmalı'::text,'toplanmalı'::text,'Kızım, güya barın kuralı: arkadaşlar sekize kadar toplanmak zorunda.'::text),
(296631,32959,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a barátoknak nyolcig ... összegyűlniük. Bárszabály.'::text,'kell'::text,'kell'::text,'kellene'::text,'Csajszi, állítólag a barátoknak nyolcig kell összegyűlniük. Bárszabály.'::text),
(306624,34070,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund macht Lärm direkt ... ihrem Handy.'::text,'vor'::text,'auf'::text,'an'::text,'Der Hund macht Lärm direkt vor ihrem Handy.'::text),
(306628,34070,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собака шумить просто ... її телефоном.'::text,'перед'::text,'на'::text,'біля'::text,'Собака шумить просто перед її телефоном.'::text),
(306627,34070,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro hace ruido justo ... de su móvil.'::text,'delante'::text,'sobre'::text,'a'::text,'El perro hace ruido justo delante de su móvil.'::text),
(306626,34070,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien fait du bruit juste ... son téléphone.'::text,'devant'::text,'sur'::text,'à'::text,'Le chien fait du bruit juste devant son téléphone.'::text),
