(306645,34072,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ese perrito hace tanto ..., en serio.'::text,'ruido'::text,'ruido'::text,'un ruido'::text,'Tío, ese perrito hace tanto ruido, en serio.'::text),
(306644,34072,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ce petit chien fait tellement de ..., sans mentir.'::text,'bruit'::text,'bruit'::text,'un bruit'::text,'Frérot, ce petit chien fait tellement de bruit, sans mentir.'::text),
