(306648,34072,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a kis kutya annyi ... csap, komolyan.'::text,'zajt'::text,'zajt'::text,'egy zajt'::text,'Tesó, az a kis kutya annyi zajt csap, komolyan.'::text),
(316299,35145,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Die Dusche ist ... der Wand direkt hinter dem Klo!'::text,'an'::text,'in'::text,'an'::text,'Albtraum! Die Dusche ist an der Wand direkt hinter dem Klo!'::text),
(316303,35145,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кошмар! Душ ... стіні просто за унітазом!'::text,'на'::text,'у'::text,'біля'::text,'Кошмар! Душ на стіні просто за унітазом!'::text),
(316302,35145,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué pesadilla! ¡La ducha está ... la pared, justo detrás del váter!'::text,'en'::text,'en'::text,'a'::text,'¡Qué pesadilla! ¡La ducha está en la pared, justo detrás del váter!'::text),
(316301,35145,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! La douche est ... le mur juste derrière les toilettes !'::text,'sur'::text,'dans'::text,'à'::text,'Cauchemar ! La douche est sur le mur juste derrière les toilettes !'::text),
(316304,35145,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Duş tam tuvaletin arkasındaki ...!'::text,'duvarda'::text,'duvarın içinde'::text,'duvarın yanında'::text,'Kâbus! Duş tam tuvaletin arkasındaki duvarda!'::text),
(316305,35145,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A zuhany ... van, közvetlenül a vécé mögött!'::text,'a falon'::text,'a falban'::text,'a falnál'::text,'Rémálom! A zuhany a falon van, közvetlenül a vécé mögött!'::text),
(316317,35147,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann badet normalerweise, aber gestern ... er eine Dusche.'::text,'nahm'::text,'nimmt'::text,NULL::text,'Der Mann badet normalerweise, aber gestern nahm er eine Dusche.'::text),
(316321,35147,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік зазвичай приймає ванну, але вчора він ... душ.'::text,'прийняв'::text,'приймає'::text,NULL::text,'Чоловік зазвичай приймає ванну, але вчора він прийняв душ.'::text),
(316320,35147,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre suele darse un baño, pero ayer él se ... una ducha.'::text,'dio'::text,'da'::text,NULL::text,'El hombre suele darse un baño, pero ayer él se dio una ducha.'::text),
(316319,35147,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme prend d''habitude un bain, mais hier il ... une douche.'::text,'a pris'::text,'prend'::text,NULL::text,'L''homme prend d''habitude un bain, mais hier il a pris une douche.'::text),
(316322,35147,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam genelde küvette yıkanır ama dün duş ...'::text,'aldı'::text,'alır'::text,NULL::text,'Adam genelde küvette yıkanır ama dün duş aldı.'::text),
(316323,35147,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi általában kádban fürdik, de tegnap ő ...'::text,'lezuhanyozott'::text,'lezuhanyozik'::text,NULL::text,'A férfi általában kádban fürdik, de tegnap ő lezuhanyozott.'::text),
(294330,32704,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise duschst du, aber heute ... du die Wanne. Stark.'::text,'füllst'::text,'füllst'::text,NULL::text,'Normalerweise duschst du, aber heute füllst du die Wanne. Stark.'::text),
(294334,32704,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай ти приймаєш душ, але сьогодні ... ванну. Елегантно.'::text,'набираєш'::text,'набираєш'::text,NULL::text,'Зазвичай ти приймаєш душ, але сьогодні набираєш ванну. Елегантно.'::text),
(294333,32704,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente tú te duchas, pero hoy ... la bañera. Qué estilo.'::text,'estás llenando'::text,'llenas'::text,NULL::text,'Normalmente tú te duchas, pero hoy estás llenando la bañera. Qué estilo.'::text),
(294332,32704,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu prends des douches, mais aujourd''hui tu ... la baignoire. Stylé.'::text,'es en train de remplir'::text,'remplis'::text,NULL::text,'D''habitude tu prends des douches, mais aujourd''hui tu es en train de remplir la baignoire. Stylé.'::text),
