(326307,36257,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist der Sand warm? Weil die Sonne scheint.'::text,'Warum'::text,'Wer'::text,'Was'::text,'Warum ist der Sand warm? Weil die Sonne scheint.'::text),
(326311,36257,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... пісок теплий? Бо світить сонце.'::text,'Чому'::text,'Хто'::text,'Що'::text,'Чому пісок теплий? Бо світить сонце.'::text),
