(326309,36257,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le sable est-il chaud ? Parce que le soleil brille.'::text,'Pourquoi'::text,'Qui'::text,'Que'::text,'Pourquoi le sable est-il chaud ? Parce que le soleil brille.'::text),
(326312,36257,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kum ... sıcak? Çünkü güneş açmış.'::text,'neden'::text,'kim'::text,'ne'::text,'Kum neden sıcak? Çünkü güneş açmış.'::text),
(326313,36257,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... meleg a homok? Mert süt a nap.'::text,'Miért'::text,'Ki'::text,'Mi'::text,'Miért meleg a homok? Mert süt a nap.'::text),
(322671,35853,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt! Du ... richtig gut mit dichten Bärten.'::text,'bist'::text,'ist'::text,'bin'::text,'Respekt! Du bist richtig gut mit dichten Bärten.'::text),
