(322674,35853,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Respeto! Tú ... genial con las barbas espesas.'::text,'eres'::text,'es'::text,'soy'::text,'¡Respeto! Tú eres genial con las barbas espesas.'::text),
