(322680,35854,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Barbier rasiert normalerweise Kinne, aber jetzt ... er einen dichten Bart.'::text,'kämmt'::text,'kämmt'::text,NULL::text,'Der Barbier rasiert normalerweise Kinne, aber jetzt kämmt er einen dichten Bart.'::text),
(322684,35854,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Барбер зазвичай голить підборіддя, але зараз він ... густу бороду.'::text,'розчісує'::text,'розчісує'::text,NULL::text,'Барбер зазвичай голить підборіддя, але зараз він розчісує густу бороду.'::text),
