(322682,35854,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le barbier rase d''habitude des mentons, mais maintenant il ... une barbe épaisse.'::text,'est en train de peigner'::text,'peigne'::text,NULL::text,'Le barbier rase d''habitude des mentons, mais maintenant il est en train de peigner une barbe épaisse.'::text),
