(310476,34498,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ich will direkt hier unter ... schlafen.'::text,'diesen Postern'::text,'diesem Poster'::text,'jenen Postern'::text,'Alter, ich will direkt hier unter diesen Postern schlafen.'::text),
(310480,34498,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, я хочу спати під ... прямо тут.'::text,'цими постерами'::text,'цими постерами'::text,'тим постером'::text,'Бро, я хочу спати під цими постерами прямо тут.'::text),
(310479,34498,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, yo quiero dormir bajo ... aquí mismo.'::text,'estos pósteres'::text,'este póster'::text,'esos pósteres'::text,'Tío, yo quiero dormir bajo estos pósteres aquí mismo.'::text),
(310478,34498,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, je veux dormir sous ... juste ici.'::text,'ces posters'::text,'ce poster'::text,'ces posters'::text,'Frérot, je veux dormir sous ces posters juste ici.'::text),
