(310482,34498,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, én itt akarok aludni ... alatt.'::text,'ezek a poszterek'::text,'ez a poszter'::text,'azok a poszterek'::text,'Tesó, én itt akarok aludni ezek a poszterek alatt.'::text),
(310512,34502,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'An der Wand ist nicht viel ... wegen der Poster.'::text,'Platz'::text,'Platz'::text,'ein Platz'::text,'An der Wand ist nicht viel Platz wegen der Poster.'::text),
(310516,34502,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На стіні немає багато ... через постери.'::text,'місця'::text,'місць'::text,'місця'::text,'На стіні немає багато місця через постери.'::text),
(310515,34502,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No hay mucho ... en la pared por los pósteres.'::text,'espacio'::text,'espacio'::text,'un espacio'::text,'No hay mucho espacio en la pared por los pósteres.'::text),
