(319228,35470,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, наступного разу ти ... стартувати першим, респект.'::text,'збираєшся'::text,'збираєшся'::text,'збираєшся'::text,'Чесно, наступного разу ти збираєшся стартувати першим, респект.'::text),
