(319226,35470,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, la prochaine fois tu ... partir en premier, respect.'::text,'vas'::text,'vas'::text,'vas'::text,'Franchement, la prochaine fois tu vas partir en premier, respect.'::text),
(319229,35470,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen bir dahaki sefere ilk ..., helal.'::text,'başlayacaksın'::text,'başlayacaksın'::text,'başlayacaksın'::text,'Açıkçası sen bir dahaki sefere ilk başlayacaksın, helal.'::text),
(319230,35470,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te legközelebb elsőként ... rajtolni, respekt.'::text,'fogsz'::text,'fogsz'::text,'fogsz'::text,'Őszintén, te legközelebb elsőként fogsz rajtolni, respekt.'::text),
(299415,33269,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! ... du Hilfe holen? Das ist eine Katastrophe!'::text,'Kannst'::text,NULL::text,'Bist'::text,'Nein! Kannst du Hilfe holen? Das ist eine Katastrophe!'::text),
(299419,33269,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Чи ... ти отримати допомогу? Це катастрофа!'::text,'можеш'::text,NULL::text,'є'::text,'Ні! Чи можеш ти отримати допомогу? Це катастрофа!'::text),
(299418,33269,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¿... tú conseguir ayuda? ¡Esto es un desastre!'::text,'Puedes'::text,NULL::text,'Estás'::text,'¡No! ¿Puedes tú conseguir ayuda? ¡Esto es un desastre!'::text),
(299417,33269,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! Est-ce que tu ... trouver de l''aide ? C''est une catastrophe !'::text,'peux'::text,NULL::text,'es'::text,'Non ! Est-ce que tu peux trouver de l''aide ? C''est une catastrophe !'::text),
(299420,33269,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Sen yardım ... misin? Bu bir felaket!'::text,'alabilir'::text,NULL::text,NULL::text,'Hayır! Sen yardım alabilir misin? Bu bir felaket!'::text),
(299421,33269,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem! ... te segítséget szerezni? Ez katasztrófa!'::text,'Tudsz'::text,NULL::text,'Vagy'::text,'Nem! Tudsz te segítséget szerezni? Ez katasztrófa!'::text),
(299460,33274,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, da ... Taschentücher zur Hilfe direkt auf dem Schreibtisch, Bro.'::text,'sind'::text,'ist'::text,'sein'::text,'Yo, da sind Taschentücher zur Hilfe direkt auf dem Schreibtisch, Bro.'::text),
(299464,33274,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, прямо на столі ... серветки на допомогу, бро.'::text,'є'::text,'є'::text,'бути'::text,'Йо, прямо на столі є серветки на допомогу, бро.'::text),
(299463,33274,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, ... pañuelos para ayudar justo en el escritorio, tío.'::text,'hay'::text,'hay'::text,'hay'::text,'Ey, hay pañuelos para ayudar justo en el escritorio, tío.'::text),
(299462,33274,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... des mouchoirs pour aider juste sur le bureau, frérot.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Yo, il y a des mouchoirs pour aider juste sur le bureau, frérot.'::text),
(299465,33274,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hey, tam masanın üstünde yardım için mendil ..., kanka.'::text,'var'::text,'var'::text,'olmak'::text,'Hey, tam masanın üstünde yardım için mendil var, kanka.'::text),
(299466,33274,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hé, közvetlenül az asztalon ... zsebkendők segítségnek, tesó.'::text,'vannak'::text,'van'::text,'lenni'::text,'Hé, közvetlenül az asztalon vannak zsebkendők segítségnek, tesó.'::text),
(299082,33232,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tut er in sein gesundes Getränk? Spinat.'::text,'Was'::text,'Wer'::text,'Wo'::text,'Was tut er in sein gesundes Getränk? Spinat.'::text),
(299086,33232,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він кладе у свій корисний напій? Шпинат.'::text,'Що'::text,'Хто'::text,'Де'::text,'Що він кладе у свій корисний напій? Шпинат.'::text),
(299085,33232,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... pone él en su bebida saludable? Espinacas.'::text,'Qué'::text,'Quién'::text,'Dónde'::text,'¿Qué pone él en su bebida saludable? Espinacas.'::text),
(299084,33232,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... met-il dans sa boisson saine ? Des épinards.'::text,'Que'::text,'Qui'::text,'Où'::text,'Que met-il dans sa boisson saine ? Des épinards.'::text),
(299087,33232,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sağlıklı içeceğine ... koyuyor? Ispanak.'::text,'ne'::text,'kim'::text,'nerede'::text,'O sağlıklı içeceğine ne koyuyor? Ispanak.'::text),
