(299118,33236,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es ist Morgen, also ... er gerade ein gesundes Morgengetränk.'::text,'macht'::text,'macht'::text,NULL::text,'Es ist Morgen, also macht er gerade ein gesundes Morgengetränk.'::text),
(299122,33236,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз ранок, тож він саме зараз ... корисний ранковий напій.'::text,'готує'::text,'готує'::text,NULL::text,'Зараз ранок, тож він саме зараз готує корисний ранковий напій.'::text),
(299121,33236,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es por la mañana, así que él ... una bebida saludable de mañana ahora mismo.'::text,'está preparando'::text,'prepara'::text,NULL::text,'Es por la mañana, así que él está preparando una bebida saludable de mañana ahora mismo.'::text),
(299120,33236,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est le matin, donc il ... une boisson saine du matin en ce moment.'::text,'est en train de préparer'::text,'prépare'::text,NULL::text,'C''est le matin, donc il est en train de préparer une boisson saine du matin en ce moment.'::text),
(299123,33236,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabah, bu yüzden o şu an sağlıklı bir sabah içeceği ...'::text,'yapıyor'::text,'yapar'::text,NULL::text,'Sabah, bu yüzden o şu an sağlıklı bir sabah içeceği yapıyor.'::text),
