(327013,36335,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вітає водій? Людей у своєму автобусі.'::text,'Кого'::text,'Де'::text,'Коли'::text,'Кого вітає водій? Людей у своєму автобусі.'::text),
(327012,36335,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... da la bienvenida el conductor? A la gente de su autobús.'::text,'A quién'::text,'Dónde'::text,'Cuándo'::text,'¿A quién da la bienvenida el conductor? A la gente de su autobús.'::text),
