(327014,36335,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şoför ... karşılıyor? Otobüsündeki insanları.'::text,'kimi'::text,'nerede'::text,'ne zaman'::text,'Şoför kimi karşılıyor? Otobüsündeki insanları.'::text),
(327015,36335,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... üdvözöl a sofőr? Az embereket a buszán.'::text,'Kit'::text,'Hol'::text,'Mikor'::text,'Kit üdvözöl a sofőr? Az embereket a buszán.'::text),
(311826,34648,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sie ihr Buch an der Bushaltestelle lesen? Ja, kann sie.'::text,'Kann'::text,'Ist'::text,NULL::text,'Kann sie ihr Buch an der Bushaltestelle lesen? Ja, kann sie.'::text),
(311830,34648,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чи ... вона читати свою книжку на зупинці? Так, може.'::text,'може'::text,'є'::text,NULL::text,'Чи може вона читати свою книжку на зупинці? Так, може.'::text),
(311829,34648,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... ella leer su libro en la parada de autobús? Sí, puede.'::text,'Puede'::text,'Está'::text,NULL::text,'¿Puede ella leer su libro en la parada de autobús? Sí, puede.'::text),
(311828,34648,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Est-ce qu''elle ... lire son livre à l''arrêt de bus ? Oui, elle peut.'::text,'peut'::text,'est'::text,NULL::text,'Est-ce qu''elle peut lire son livre à l''arrêt de bus ? Oui, elle peut.'::text),
(311831,34648,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O otobüs durağında kitabını ... mi? Evet, okuyabilir.'::text,'okuyabilir'::text,NULL::text,NULL::text,'O otobüs durağında kitabını okuyabilir mi? Evet, okuyabilir.'::text),
(311832,34648,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ő olvasni a könyvét a buszmegállóban? Igen, tud.'::text,'Tud'::text,'Van'::text,NULL::text,'Tud ő olvasni a könyvét a buszmegállóban? Igen, tud.'::text),
(311853,34651,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kein Bus, der schlimmste Tag überhaupt! Na gut, dann ... ich hier mein Buch lesen!'::text,'werde'::text,'werde'::text,NULL::text,'Kein Bus, der schlimmste Tag überhaupt! Na gut, dann werde ich hier mein Buch lesen!'::text),
(311857,34651,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жодного автобуса, найгірший день у житті! Гаразд, я ... тут свою книжку!'::text,'читатиму'::text,'збираюся читати'::text,NULL::text,'Жодного автобуса, найгірший день у житті! Гаразд, я читатиму тут свою книжку!'::text),
