(311855,34651,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pas de bus, le pire jour de ma vie ! Bon, je ... mon livre ici !'::text,'lirai'::text,'vais lire'::text,NULL::text,'Pas de bus, le pire jour de ma vie ! Bon, je lirai mon livre ici !'::text),
