(325383,36154,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... arriba en el autobús rojo.'::text,'está'::text,'están'::text,'estoy'::text,'El hombre está arriba en el autobús rojo.'::text),
