(325386,36154,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi ... fent a piros buszon.'::text,'van'::text,'vannak'::text,'vagyok'::text,'A férfi van fent a piros buszon.'::text),
(325389,36155,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... nach oben, weil das Oberdeck des Busses nicht unten war.'::text,'ging'::text,'geht'::text,'ging'::text,'Er ging nach oben, weil das Oberdeck des Busses nicht unten war.'::text),
