(305287,33921,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кав''ярня ... дві великі дошки з меню.'::text,'має'::text,'мати'::text,'має'::text,'Кав''ярня має дві великі дошки з меню.'::text),
