(298548,33172,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a terem itt nagy, mert nem kicsi.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a terem itt nagy, mert nem kicsi.'::text),
