(298583,33176,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdi o salonda mermer bir masada ...'::text,'oturuyor'::text,'oturur'::text,'oturuyor'::text,'Şimdi o salonda mermer bir masada oturuyor.'::text),
