(305610,33957,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... el calendario a un nuevo mes.'::text,'está pasando'::text,'pasa'::text,'está pasando'::text,'Él está pasando el calendario a un nuevo mes.'::text),
(305609,33957,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le calendrier à un nouveau mois.'::text,'est en train de tourner'::text,'tourne'::text,'est en train de tourner'::text,'Il est en train de tourner le calendrier à un nouveau mois.'::text),
