(294996,32778,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... das große Objektiv in einer Sekunde scharfstellen.'::text,'kannst'::text,'kannst'::text,'kannst'::text,'Ehrlich, du kannst das große Objektiv in einer Sekunde scharfstellen.'::text),
