(295001,32778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen o büyük objektifi bir saniyede ...'::text,'netleyebilirsin'::text,'netleyebilirsin'::text,'netleyebilirsin'::text,'Açıkçası sen o büyük objektifi bir saniyede netleyebilirsin.'::text),
