(310615,34513,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Водоспад ... дуже потужний.'::text,'є'::text,'є'::text,'є'::text,'Водоспад є дуже потужний.'::text),
(310614,34513,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cascada ... muy potente.'::text,'es'::text,'son'::text,'soy'::text,'La cascada es muy potente.'::text),
(310613,34513,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cascade ... très puissante.'::text,'est'::text,'sont'::text,'suis'::text,'La cascade est très puissante.'::text),
(310616,34513,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şelale çok güçlü ...'::text,''::text,NULL::text,NULL::text,'Şelale çok güçlü.'::text),
(310617,34513,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vízesés ... nagyon erős.'::text,''::text,NULL::text,'vagyok'::text,'A vízesés nagyon erős.'::text),
(310629,34515,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, schau dir diese krasse Gischt an. Er ... klatschnass werden, ohne Witz.'::text,'wird'::text,'wird'::text,NULL::text,'Bro, schau dir diese krasse Gischt an. Er wird klatschnass werden, ohne Witz.'::text),
(310633,34515,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, глянь на ці потужні бризки. Він ... до нитки, без жартів.'::text,'збирається промокнути'::text,'промокне'::text,NULL::text,'Бро, глянь на ці потужні бризки. Він збирається промокнути до нитки, без жартів.'::text),
(310632,34515,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, mira qué rociada tan fuerte. Él ... empapado, en serio.'::text,'va a acabar'::text,'acabará'::text,NULL::text,'Tío, mira qué rociada tan fuerte. Él va a acabar empapado, en serio.'::text),
(310631,34515,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, regarde ces embruns puissants. Il ... trempé, sans mentir.'::text,'va finir'::text,'finira'::text,NULL::text,'Frérot, regarde ces embruns puissants. Il va finir trempé, sans mentir.'::text),
(310634,34515,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, şu güçlü serpintiye bak. O sırılsıklam ..., cidden.'::text,'olacak'::text,'olacak'::text,NULL::text,'Kanka, şu güçlü serpintiye bak. O sırılsıklam olacak, cidden.'::text),
(310635,34515,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nézd azt az erős permetet. Ő bőrig ... ázni, komolyan.'::text,'fog'::text,'fog'::text,NULL::text,'Tesó, nézd azt az erős permetet. Ő bőrig fog ázni, komolyan.'::text),
(302061,33563,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der nette Mann ... für alle Kinder Pfannkuchen machen.'::text,'kann'::text,'kann'::text,'kann'::text,'Der nette Mann kann für alle Kinder Pfannkuchen machen.'::text),
(302065,33563,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Добрий чоловік ... спекти млинці для всіх дітей.'::text,'може'::text,'може'::text,'може'::text,'Добрий чоловік може спекти млинці для всіх дітей.'::text),
(302064,33563,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre amable ... hacer tortitas para todos los niños.'::text,'puede'::text,'puede'::text,'puede'::text,'El hombre amable puede hacer tortitas para todos los niños.'::text),
(302063,33563,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gentil monsieur ... faire des crêpes pour tous les enfants.'::text,'peut'::text,'peut'::text,'peut'::text,'Le gentil monsieur peut faire des crêpes pour tous les enfants.'::text),
(302066,33563,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nazik adam bütün çocuklar için krep ...'::text,'yapabilir'::text,'yapabilir'::text,'yapabilir'::text,'Nazik adam bütün çocuklar için krep yapabilir.'::text),
(302067,33563,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kedves férfi ... palacsintát sütni az összes gyereknek.'::text,'tud'::text,'tud'::text,'tud'::text,'A kedves férfi tud palacsintát sütni az összes gyereknek.'::text),
(302115,33569,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat gesagt, er hat ihren Weg so ... freigeräumt.'::text,'freundlich'::text,'freundlich'::text,'Freundlichkeit'::text,'Bestie, sie hat gesagt, er hat ihren Weg so freundlich freigeräumt.'::text),
(302119,33569,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона казала, що він так ... розчистив їй доріжку.'::text,'люб''язно'::text,'люб''язний'::text,'люб''язність'::text,'Подруго, вона казала, що він так люб''язно розчистив їй доріжку.'::text),
(302118,33569,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, ella dijo que él le despejó el camino tan ...'::text,'amablemente'::text,'amable'::text,'amabilidad'::text,'Amiga, ella dijo que él le despejó el camino tan amablemente.'::text),
(302117,33569,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle a dit qu''il a dégagé son chemin si ...'::text,'gentiment'::text,'gentil'::text,'gentillesse'::text,'Ma belle, elle a dit qu''il a dégagé son chemin si gentiment.'::text),
(302120,33569,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, o dedi ki adam onun yolunu çok ... temizlemiş.'::text,'nazikçe'::text,'nazik'::text,'naziklik'::text,'Kankam, o dedi ki adam onun yolunu çok nazikçe temizlemiş.'::text),
(302121,33569,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő azt mondta, hogy a férfi olyan ... takarította el az útját.'::text,'kedvesen'::text,'kedves'::text,'kedvesség'::text,'Csajszi, ő azt mondta, hogy a férfi olyan kedvesen takarította el az útját.'::text),
(310773,34531,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie ... den Tisch für eine Party vor, so cool.'::text,'bereitet'::text,'bereiten'::text,'vorbereitend'::text,'Alter, sie bereitet den Tisch für eine Party vor, so cool.'::text),
(310777,34531,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... стіл до вечірки, так круто.'::text,'готує'::text,'готувати'::text,'готуючи'::text,'Бро, вона готує стіл до вечірки, так круто.'::text),
(310776,34531,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella ... la mesa para una fiesta, qué guay.'::text,'prepara'::text,'preparar'::text,'preparando'::text,'Tío, ella prepara la mesa para una fiesta, qué guay.'::text),
(310775,34531,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... la table pour une fête, trop cool.'::text,'prépare'::text,'préparer'::text,'préparant'::text,'Frérot, elle prépare la table pour une fête, trop cool.'::text),
(310778,34531,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o parti için masayı ..., çok havalı.'::text,'hazırlar'::text,'hazırlamak'::text,'hazırlayarak'::text,'Kanka, o parti için masayı hazırlar, çok havalı.'::text),
(310779,34531,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő ... az asztalt egy bulira, nagyon menő.'::text,'előkészíti'::text,'előkészíteni'::text,'előkészítő'::text,'Tesó, ő előkészíti az asztalt egy bulira, nagyon menő.'::text),
(310800,34534,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Abendessen ist abends, also ... sie das Abendessen für heute Abend zubereiten.'::text,'wird'::text,'wird'::text,'wird'::text,'Das Abendessen ist abends, also wird sie das Abendessen für heute Abend zubereiten.'::text),
(310804,34534,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вечеря ввечері, тож вона ... вечерю на сьогоднішній вечір.'::text,'збирається приготувати'::text,'збирається приготувати'::text,'збирається приготувати'::text,'Вечеря ввечері, тож вона збирається приготувати вечерю на сьогоднішній вечір.'::text),
(310803,34534,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cena es por la noche, así que ella ... la cena para esta noche.'::text,'va a preparar'::text,'va a preparar'::text,'va a preparar'::text,'La cena es por la noche, así que ella va a preparar la cena para esta noche.'::text),
(310802,34534,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dîner, c''est le soir, donc elle ... le dîner pour ce soir.'::text,'va préparer'::text,'va préparer'::text,'va préparer'::text,'Le dîner, c''est le soir, donc elle va préparer le dîner pour ce soir.'::text),
(310805,34534,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akşam yemeği akşam olur, bu yüzden o bu akşam için akşam yemeği ...'::text,'hazırlayacak'::text,'hazırlayacak'::text,'hazırlayacak'::text,'Akşam yemeği akşam olur, bu yüzden o bu akşam için akşam yemeği hazırlayacak.'::text),
(310806,34534,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vacsora este van, ezért ő ... elkészíteni a ma esti vacsorát.'::text,'fogja'::text,'fogja'::text,'fogja'::text,'A vacsora este van, ezért ő fogja elkészíteni a ma esti vacsorát.'::text),
(298713,33191,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise reicht er Tüten rüber, aber jetzt ... er dem Kunden eine Münze.'::text,'reicht'::text,'reicht'::text,NULL::text,'Normalerweise reicht er Tüten rüber, aber jetzt reicht er dem Kunden eine Münze.'::text),
(298717,33191,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай він подає пакети, але зараз ... покупцеві монету.'::text,'подає'::text,'подає'::text,NULL::text,'Зазвичай він подає пакети, але зараз подає покупцеві монету.'::text),
(298716,33191,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente él entrega bolsas, pero ahora le ... una moneda al cliente.'::text,'está dando'::text,'da'::text,NULL::text,'Normalmente él entrega bolsas, pero ahora le está dando una moneda al cliente.'::text),
(298715,33191,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude il tend des sacs, mais maintenant il ... une pièce au client.'::text,'est en train de tendre'::text,'tend'::text,NULL::text,'D''habitude il tend des sacs, mais maintenant il est en train de tendre une pièce au client.'::text),
(298718,33191,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O genelde poşet uzatır ama şimdi müşteriye bir bozuk para ...'::text,'uzatıyor'::text,'uzatır'::text,NULL::text,'O genelde poşet uzatır ama şimdi müşteriye bir bozuk para uzatıyor.'::text),
(298719,33191,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő általában szatyrokat ad át, de most egy érmét ... a vásárlónak.'::text,'ad'::text,'ad'::text,NULL::text,'Ő általában szatyrokat ad át, de most egy érmét ad a vásárlónak.'::text),
(325893,36211,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Niemand ... diese Burg ohne Selfie besuchen!'::text,'kann'::text,'ist'::text,'sind'::text,'Katastrophe! Niemand kann diese Burg ohne Selfie besuchen!'::text),
(325897,36211,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Ніхто не ... відвідати цей замок без селфі!'::text,'може'::text,'є'::text,'є'::text,'Катастрофа! Ніхто не може відвідати цей замок без селфі!'::text),
(325896,36211,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Catástrofe! ¡Nadie ... visitar este castillo sin un selfie!'::text,'puede'::text,'está'::text,'están'::text,'¡Catástrofe! ¡Nadie puede visitar este castillo sin un selfie!'::text),
(325895,36211,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Personne ne ... visiter ce château sans selfie !'::text,'peut'::text,'est'::text,'sont'::text,'Catastrophe ! Personne ne peut visiter ce château sans selfie !'::text),
(325898,36211,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Kimse bu kaleyi selfie olmadan ...!'::text,'ziyaret edemez'::text,NULL::text,NULL::text,'Felaket! Kimse bu kaleyi selfie olmadan ziyaret edemez!'::text),
(325899,36211,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Senki sem ... meglátogatni ezt a várat szelfi nélkül!'::text,'tudja'::text,'van'::text,'vannak'::text,'Katasztrófa! Senki sem tudja meglátogatni ezt a várat szelfi nélkül!'::text),
(325938,36216,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leute, die diesen Turm besuchen, ... für den Hügel gute Schuhe tragen.'::text,'sollten'::text,'sollten'::text,'sollten'::text,'Leute, die diesen Turm besuchen, sollten für den Hügel gute Schuhe tragen.'::text),
(325942,36216,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Люди, які відвідують цю вежу, ... взути добре взуття для пагорба.'::text,'мали б'::text,'мали б'::text,'мали б'::text,'Люди, які відвідують цю вежу, мали б взути добре взуття для пагорба.'::text),
(325941,36216,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gente que visita esta torre ... llevar buen calzado para la colina.'::text,'debería'::text,'debería'::text,'debería'::text,'La gente que visita esta torre debería llevar buen calzado para la colina.'::text),
(325940,36216,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les gens qui visitent cette tour ... porter de bonnes chaussures pour la colline.'::text,'devraient'::text,'devraient'::text,'devraient'::text,'Les gens qui visitent cette tour devraient porter de bonnes chaussures pour la colline.'::text),
(325943,36216,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kuleyi ziyaret edenler tepe için iyi ayakkabı ...'::text,'giymeli'::text,'giymeli'::text,'giymeli'::text,'Bu kuleyi ziyaret edenler tepe için iyi ayakkabı giymeli.'::text),
(325944,36216,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azoknak, akik meglátogatják ezt a tornyot, jó cipőt ... hordaniuk a dombhoz.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Azoknak, akik meglátogatják ezt a tornyot, jó cipőt kellene hordaniuk a dombhoz.'::text),
(311376,34598,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Ende für den Ball! Ihre Hände ... so schnell!'::text,'sind'::text,'ist'::text,'bin'::text,'Das Ende für den Ball! Ihre Hände sind so schnell!'::text),
(311380,34598,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кінець м''ячу! Її руки ... такі швидкі!'::text,'є'::text,'є'::text,'є'::text,'Кінець м''ячу! Її руки є такі швидкі!'::text),
(311379,34598,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El fin para la pelota! ¡Sus manos ... tan rápidas!'::text,'son'::text,'es'::text,'soy'::text,'¡El fin para la pelota! ¡Sus manos son tan rápidas!'::text),
(311378,34598,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fin pour le ballon ! Ses mains ... si rapides !'::text,'sont'::text,'est'::text,'suis'::text,'La fin pour le ballon ! Ses mains sont si rapides !'::text),
(311381,34598,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topun sonu geldi! Onun elleri çok hızlı ...!'::text,''::text,NULL::text,NULL::text,'Topun sonu geldi! Onun elleri çok hızlı!'::text),
(311382,34598,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vége a labdának! A keze ... olyan gyors!'::text,''::text,NULL::text,'vagyok'::text,'Vége a labdának! A keze olyan gyors!'::text),
(311403,34601,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie hat gesagt, der Torwart ... gerade einen schnellen Hechtsprung.'::text,'macht'::text,'macht'::text,'macht'::text,'Rate mal, sie hat gesagt, der Torwart macht gerade einen schnellen Hechtsprung.'::text),
(311407,34601,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона сказала, що воротар саме зараз ... швидкий стрибок.'::text,'робить'::text,'робить'::text,'робить'::text,'Уяви, вона сказала, що воротар саме зараз робить швидкий стрибок.'::text),
(311406,34601,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, ella dijo que el portero ... una estirada rápida ahora mismo.'::text,'está haciendo'::text,'hace'::text,'está haciendo'::text,'Adivina qué, ella dijo que el portero está haciendo una estirada rápida ahora mismo.'::text),
(311405,34601,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle a dit que le gardien ... un plongeon rapide en ce moment.'::text,'est en train de faire'::text,'fait'::text,'est en train de faire'::text,'Devine quoi, elle a dit que le gardien est en train de faire un plongeon rapide en ce moment.'::text),
(311408,34601,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, o dedi ki kaleci şu an hızlı bir plonjon ...'::text,'yapıyor'::text,'yapar'::text,'yapıyor'::text,'Bil bakalım, o dedi ki kaleci şu an hızlı bir plonjon yapıyor.'::text),
(311409,34601,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, ő azt mondta, hogy a kapus most épp egy gyors vetődést ...'::text,'csinál'::text,'csinál'::text,'csinál'::text,'Képzeld, ő azt mondta, hogy a kapus most épp egy gyors vetődést csinál.'::text),
(301314,33480,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bald ... dieses Insekt ein Schmetterling.'::text,'wird'::text,'wird'::text,'wurde'::text,'Bald wird dieses Insekt ein Schmetterling.'::text),
(301318,33480,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Скоро ця комаха ... метеликом.'::text,'стане'::text,'стає'::text,'стала'::text,'Скоро ця комаха стане метеликом.'::text),
(301317,33480,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pronto este insecto se ... en mariposa.'::text,'convertirá'::text,'convierte'::text,'convirtió'::text,'Pronto este insecto se convertirá en mariposa.'::text),
(301316,33480,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bientôt, cet insecte ... un papillon.'::text,'deviendra'::text,'devient'::text,'est devenu'::text,'Bientôt, cet insecte deviendra un papillon.'::text),
(301319,33480,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yakında bu böcek bir kelebek ...'::text,'olacak'::text,'olur'::text,'oldu'::text,'Yakında bu böcek bir kelebek olacak.'::text),
(301320,33480,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamarosan ez a rovar pillangóvá ...'::text,'fog válni'::text,'válik'::text,'vált'::text,'Hamarosan ez a rovar pillangóvá fog válni.'::text),
(327774,36420,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... wünscht sie sich? Eine Reise nach Japan.'::text,'Was'::text,'Wer'::text,'Wo'::text,'Was wünscht sie sich? Eine Reise nach Japan.'::text),
(327778,36420,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона бажає? Подорож до Японії.'::text,'Чого'::text,'Хто'::text,'Де'::text,'Чого вона бажає? Подорож до Японії.'::text),
(327777,36420,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... desea ella? Un viaje a Japón.'::text,'Qué'::text,'Quién'::text,'Dónde'::text,'¿Qué desea ella? Un viaje a Japón.'::text),
(327776,36420,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... souhaite-t-elle ? Un voyage au Japon.'::text,'Que'::text,'Qui'::text,'Où'::text,'Que souhaite-t-elle ? Un voyage au Japon.'::text),
(327779,36420,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ... diliyor? Japonya''ya bir gezi.'::text,'ne'::text,'kim'::text,'nerede'::text,'O ne diliyor? Japonya''ya bir gezi.'::text),
(327780,36420,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kíván ő? Egy japán utat.'::text,'Mit'::text,'Ki'::text,'Hol'::text,'Mit kíván ő? Egy japán utat.'::text),
(327801,36423,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie so: Ich ... den besten Wunsch aller Zeiten machen, ohne Witz.'::text,'muss'::text,'muss'::text,'sollte'::text,'Alter, sie so: Ich muss den besten Wunsch aller Zeiten machen, ohne Witz.'::text),
(327805,36423,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона така: я ... загадати найкраще бажання в житті, без жартів.'::text,'мушу'::text,'маю'::text,'мала б'::text,'Бро, вона така: я мушу загадати найкраще бажання в житті, без жартів.'::text),
(327804,36423,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella en plan: yo ... pedir el mejor deseo de la historia, en serio.'::text,'debo'::text,'tengo que'::text,'debería'::text,'Tío, ella en plan: yo debo pedir el mejor deseo de la historia, en serio.'::text),
(327803,36423,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle est genre : je ... faire le meilleur vœu de tous les temps, sans mentir.'::text,'dois'::text,'dois'::text,'devrais'::text,'Frérot, elle est genre : je dois faire le meilleur vœu de tous les temps, sans mentir.'::text),
(327806,36423,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o resmen şöyle: Ben şimdiye kadarki en iyi dileği ..., cidden.'::text,'dilemeliyim'::text,'dilemek zorundayım'::text,'dilemeliyim'::text,'Kanka, o resmen şöyle: Ben şimdiye kadarki en iyi dileği dilemeliyim, cidden.'::text),
(327807,36423,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő olyan, hogy: nekem minden idők legjobb kívánságát ... kívánnom, komolyan.'::text,'kell'::text,'kell'::text,'kellene'::text,'Tesó, ő olyan, hogy: nekem minden idők legjobb kívánságát kell kívánnom, komolyan.'::text),
(320583,35621,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie reißt ... Arme hoch, weil der Erfolg so groß ist.'::text,'ihre'::text,'seine'::text,'seine'::text,'Yo, sie reißt ihre Arme hoch, weil der Erfolg so groß ist.'::text),
(320587,35621,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вона підкидає ... руки вгору, бо успіх такий великий.'::text,'свої'::text,'свої'::text,'свої'::text,'Йо, вона підкидає свої руки вгору, бо успіх такий великий.'::text),
(320586,35621,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, ella levanta ... brazos porque el éxito es enorme.'::text,'sus'::text,'sus'::text,'sus'::text,'Ey, ella levanta sus brazos porque el éxito es enorme.'::text),
(320585,35621,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, elle lève ... bras, parce que le succès est énorme.'::text,'ses'::text,'ses'::text,'ses'::text,'Yo, elle lève ses bras, parce que le succès est énorme.'::text),
(320588,35621,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hey, o ... kollarını havaya kaldırıyor çünkü başarı çok büyük.'::text,'onun'::text,'onun'::text,'onun'::text,'Hey, o onun kollarını havaya kaldırıyor çünkü başarı çok büyük.'::text),
(320589,35621,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hé, ő a magasba lendíti a ..., mert a siker hatalmas.'::text,'karjait'::text,'karjait'::text,'karjait'::text,'Hé, ő a magasba lendíti a karjait, mert a siker hatalmas.'::text),
(320619,35625,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Überall ... Luftballons! Dieser Erfolg ist komplett verrückt!'::text,'sind'::text,'ist'::text,'sein'::text,'Überall sind Luftballons! Dieser Erfolg ist komplett verrückt!'::text),
(320623,35625,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Всюди ... повітряні кульки! Цей успіх просто божевільний!'::text,'є'::text,'є'::text,'бути'::text,'Всюди є повітряні кульки! Цей успіх просто божевільний!'::text),
(320622,35625,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... globos por todas partes! ¡Este éxito es una locura total!'::text,'Hay'::text,'Hay'::text,'Hay'::text,'¡Hay globos por todas partes! ¡Este éxito es una locura total!'::text),
(320621,35625,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des ballons partout ! Ce succès est complètement fou !'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a des ballons partout ! Ce succès est complètement fou !'::text),
(320624,35625,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her yerde balon ...! Bu başarı tamamen çılgınca!'::text,'var'::text,'var'::text,'olmak'::text,'Her yerde balon var! Bu başarı tamamen çılgınca!'::text),
(320625,35625,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindenhol lufik ...! Ez a siker teljesen őrült!'::text,'vannak'::text,'van'::text,'lenni'::text,'Mindenhol lufik vannak! Ez a siker teljesen őrült!'::text),
(326928,36326,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ... seine Tasche gestern 12,95 Kilo.'::text,'wog'::text,'wiegt'::text,'wog'::text,'Hör zu, angeblich wog seine Tasche gestern 12,95 Kilo.'::text),
(326932,36326,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, його сумка вчора ... 12,95 кіло.'::text,'важила'::text,'важить'::text,'важила'::text,'Слухай, кажуть, його сумка вчора важила 12,95 кіло.'::text),
(326931,36326,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer su bolsa ... 12,95 kilos ayer.'::text,'pesó'::text,'pesa'::text,'pesó'::text,'Oye, al parecer su bolsa pesó 12,95 kilos ayer.'::text),
(326930,36326,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment son sac ... 12,95 kilos hier.'::text,'a pesé'::text,'pèse'::text,'a pesé'::text,'Écoute, apparemment son sac a pesé 12,95 kilos hier.'::text),
(326933,36326,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya onun çantası dün 12,95 kilo ...'::text,'geldi'::text,'gelir'::text,'geldi'::text,'Dinle, güya onun çantası dün 12,95 kilo geldi.'::text),
(326934,36326,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a táskája tegnap 12,95 kilót ...'::text,'nyomott'::text,'nyom'::text,'nyomott'::text,'Figyelj, állítólag a táskája tegnap 12,95 kilót nyomott.'::text),
(303663,33741,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat eine Liste. ... Liste hat zwanzig Kästchen.'::text,'Die'::text,'Eine'::text,'Eine'::text,'Er hat eine Liste. Die Liste hat zwanzig Kästchen.'::text),
(303667,33741,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він має список. ... список має двадцять клітинок.'::text,''::text,NULL::text,NULL::text,'Він має список. Список має двадцять клітинок.'::text),
(303666,33741,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él tiene una lista. ... lista tiene veinte casillas.'::text,'La'::text,'Una'::text,'Una'::text,'Él tiene una lista. La lista tiene veinte casillas.'::text),
(303665,33741,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a une liste. ... liste a vingt cases.'::text,'La'::text,'Une'::text,'Une'::text,'Il a une liste. La liste a vingt cases.'::text),
(303668,33741,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun bir listesi var. ... listede yirmi kutucuk var.'::text,''::text,'Bir'::text,'Bir'::text,'Onun bir listesi var. Listede yirmi kutucuk var.'::text),
(303669,33741,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki van egy listája. ... listán húsz négyzet van.'::text,'A'::text,'Egy'::text,'Egy'::text,'Neki van egy listája. A listán húsz négyzet van.'::text),
(303690,33744,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der schlimmste Tag! Auf seiner Liste stehen so viele ...!'::text,'Informationen'::text,'Informationen'::text,'eine Information'::text,'Der schlimmste Tag! Auf seiner Liste stehen so viele Informationen!'::text),
(303694,33744,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Найгірший день! У його списку стільки ...!'::text,'інформації'::text,'інформації'::text,'інформації'::text,'Найгірший день! У його списку стільки інформації!'::text),
(303693,33744,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El peor día! ¡Su lista tiene tanta ...!'::text,'información'::text,'información'::text,'una información'::text,'¡El peor día! ¡Su lista tiene tanta información!'::text),
(303692,33744,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pire jour ! Sa liste contient tellement d''... !'::text,'informations'::text,'informations'::text,'une information'::text,'Le pire jour ! Sa liste contient tellement d''informations !'::text),
(303695,33744,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En kötü gün! Onun listesinde o kadar çok ... var ki!'::text,'bilgi'::text,'bilgiler'::text,'bir bilgi'::text,'En kötü gün! Onun listesinde o kadar çok bilgi var ki!'::text),
(303696,33744,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legrosszabb nap! Annyi ... van a listáján!'::text,'információ'::text,'információ'::text,'egy információ'::text,'A legrosszabb nap! Annyi információ van a listáján!'::text),
(320655,35629,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat einen Koffer! Oh nein, ... Koffer ist komplett leer!'::text,'der'::text,'ein'::text,'ein'::text,'Sie hat einen Koffer! Oh nein, der Koffer ist komplett leer!'::text),
(320659,35629,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона має валізу! О ні, ... валіза абсолютно порожня!'::text,''::text,NULL::text,NULL::text,'Вона має валізу! О ні, валіза абсолютно порожня!'::text),
(320658,35629,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella tiene una maleta! ¡Oh, no, ... maleta está completamente vacía!'::text,'la'::text,'una'::text,'una'::text,'¡Ella tiene una maleta! ¡Oh, no, la maleta está completamente vacía!'::text),
(320657,35629,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a une valise ! Oh non, ... valise est complètement vide !'::text,'la'::text,'une'::text,'une'::text,'Elle a une valise ! Oh non, la valise est complètement vide !'::text),
(320660,35629,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun bir bavulu var! Olamaz, ... bavul tamamen boş!'::text,''::text,'bir'::text,'bir'::text,'Onun bir bavulu var! Olamaz, bavul tamamen boş!'::text),
(320661,35629,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki van egy bőröndje! Jaj ne, ... bőrönd teljesen üres!'::text,'a'::text,'egy'::text,'egy'::text,'Neki van egy bőröndje! Jaj ne, a bőrönd teljesen üres!'::text),
(320700,35634,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... ein Koffer neben der Frau.'::text,'ist'::text,'sind'::text,'sein'::text,'Da ist ein Koffer neben der Frau.'::text),
(320704,35634,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поруч із жінкою ... валіза.'::text,'є'::text,'є'::text,'бути'::text,'Поруч із жінкою є валіза.'::text),
(320703,35634,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una maleta al lado de la mujer.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay una maleta al lado de la mujer.'::text),
(320702,35634,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... une valise à côté de la femme.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a une valise à côté de la femme.'::text),
(320705,35634,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadının yanında bir bavul ...'::text,'var'::text,'var'::text,'olmak'::text,'Kadının yanında bir bavul var.'::text),
(320706,35634,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő mellett ... egy bőrönd.'::text,'van'::text,'vannak'::text,'lenni'::text,'A nő mellett van egy bőrönd.'::text),
(317091,35233,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hat großes Geschick mit der Pfanne? Der Koch in der Mitte.'::text,'Wer'::text,'Was'::text,'Wo'::text,'Wer hat großes Geschick mit der Pfanne? Der Koch in der Mitte.'::text),
(317095,35233,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... має чудову вправність зі сковородою? Шеф-кухар посередині.'::text,'Хто'::text,'Що'::text,'Де'::text,'Хто має чудову вправність зі сковородою? Шеф-кухар посередині.'::text),
(317094,35233,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... tiene gran habilidad con la sartén? El chef del medio.'::text,'Quién'::text,'Qué'::text,'Dónde'::text,'¿Quién tiene gran habilidad con la sartén? El chef del medio.'::text),
(317093,35233,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a un grand talent avec la poêle ? Le chef au milieu.'::text,'Qui'::text,'Que'::text,'Où'::text,'Qui a un grand talent avec la poêle ? Le chef au milieu.'::text),
(317096,35233,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavayı ... çok ustaca kullanıyor? Ortadaki şef.'::text,'kim'::text,'ne'::text,'nerede'::text,'Tavayı kim çok ustaca kullanıyor? Ortadaki şef.'::text),
(317097,35233,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ügyes nagyon a serpenyővel? A középen álló séf.'::text,'Ki'::text,'Mi'::text,'Hol'::text,'Ki ügyes nagyon a serpenyővel? A középen álló séf.'::text),
(327432,36382,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... nach dem Rennen eine Medaille.'::text,'gewinnt'::text,'gewinnen'::text,'gewinnend'::text,'Er gewinnt nach dem Rennen eine Medaille.'::text),
(327436,36382,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... медаль після забігу.'::text,'здобуває'::text,'здобувати'::text,'здобуваючи'::text,'Він здобуває медаль після забігу.'::text),
(327435,36382,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... una medalla después de la carrera.'::text,'gana'::text,'ganar'::text,'ganando'::text,'Él gana una medalla después de la carrera.'::text),
(327434,36382,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... une médaille après la course.'::text,'gagne'::text,'gagner'::text,'gagnant'::text,'Il gagne une médaille après la course.'::text),
(327437,36382,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yarıştan sonra bir madalya ...'::text,'kazanır'::text,'kazanmak'::text,'kazanarak'::text,'O yarıştan sonra bir madalya kazanır.'::text),
(327438,36382,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... egy érmet a verseny után.'::text,'nyer'::text,'nyerni'::text,'nyerő'::text,'Ő nyer egy érmet a verseny után.'::text),
(327468,36386,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Läufer 299 ... gerade eine Medaille, voll im Plan.'::text,'gewinnt'::text,'gewinnt'::text,'gewinnt'::text,'Läufer 299 gewinnt gerade eine Medaille, voll im Plan.'::text),
(327472,36386,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бігун 299 саме зараз ... медаль, за планом.'::text,'виграє'::text,'виграє'::text,'виграє'::text,'Бігун 299 саме зараз виграє медаль, за планом.'::text),
(327471,36386,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El corredor 299 ... una medalla ahora mismo, según lo previsto.'::text,'está ganando'::text,'gana'::text,'está ganando'::text,'El corredor 299 está ganando una medalla ahora mismo, según lo previsto.'::text),
(327470,36386,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le coureur 299 ... une médaille en ce moment, objectif atteint.'::text,'est en train de gagner'::text,'gagne'::text,'est en train de gagner'::text,'Le coureur 299 est en train de gagner une médaille en ce moment, objectif atteint.'::text),
(327473,36386,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'299 numaralı koşucu şu an bir madalya ..., hedefe uygun.'::text,'kazanıyor'::text,'kazanır'::text,'kazanıyor'::text,'299 numaralı koşucu şu an bir madalya kazanıyor, hedefe uygun.'::text),
(327474,36386,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A 299-es futó most épp egy érmet ..., a terv szerint.'::text,'nyer'::text,'nyer'::text,'nyer'::text,'A 299-es futó most épp egy érmet nyer, a terv szerint.'::text),
(323670,35964,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf ihrer Tour isst sie ... Nacht Dumplings.'::text,'in der'::text,'in der'::text,'an der'::text,'Auf ihrer Tour isst sie in der Nacht Dumplings.'::text),
(323674,35964,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Під час своєї подорожі вона їсть дамплінги ... ночі.'::text,'у'::text,'у'::text,'на'::text,'Під час своєї подорожі вона їсть дамплінги у ночі.'::text),
(323673,35964,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En su viaje, ella come dumplings ... noche.'::text,'por la'::text,'en la'::text,'sobre la'::text,'En su viaje, ella come dumplings por la noche.'::text),
(323672,35964,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant son tour, elle mange des dumplings ... la nuit.'::text,''::text,'dans'::text,'sur'::text,'Pendant son tour, elle mange des dumplings la nuit.'::text),
(323675,35964,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gezisinde o gece ... dumpling yiyor.'::text,''::text,NULL::text,NULL::text,'Gezisinde o gece dumpling yiyor.'::text),
(323676,35964,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az útján ő ... dumplingot eszik.'::text,'éjszaka'::text,'éjszakában'::text,'éjszakán'::text,'Az útján ő éjszaka dumplingot eszik.'::text),
(323688,35966,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine langweilige Tour, klar. Sie hatte dort so wenig ...'::text,'Spaß'::text,'Spaß'::text,'Spiele'::text,'Eine langweilige Tour, klar. Sie hatte dort so wenig Spaß.'::text),
(323692,35966,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Нудна подорож, звісно. Вона мала там так мало ...'::text,'задоволення'::text,'задоволення'::text,'ігор'::text,'Нудна подорож, звісно. Вона мала там так мало задоволення.'::text),
(323691,35966,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un viaje aburrido, claro. Ella tuvo tan poca ... allí.'::text,'diversión'::text,'diversión'::text,'juegos'::text,'Un viaje aburrido, claro. Ella tuvo tan poca diversión allí.'::text),
(323690,35966,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un tour ennuyeux, évidemment. Elle a eu si peu de ... là-bas.'::text,'plaisir'::text,'plaisir'::text,'jeux'::text,'Un tour ennuyeux, évidemment. Elle a eu si peu de plaisir là-bas.'::text),
(323693,35966,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıkıcı bir gezi, belli ki. O orada çok az ... yaşadı.'::text,'eğlence'::text,'eğlenceler'::text,'oyunlar'::text,'Sıkıcı bir gezi, belli ki. O orada çok az eğlence yaşadı.'::text),
(323694,35966,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unalmas út, nyilván. Neki olyan kevés ... volt ott.'::text,'móka'::text,'móka'::text,'játék'::text,'Unalmas út, nyilván. Neki olyan kevés móka volt ott.'::text),
(299478,33276,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du ... Leuten so schnell helfen.'::text,'kannst'::text,'kannst'::text,'kannst'::text,'Respekt, du kannst Leuten so schnell helfen.'::text),
(299482,33276,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти ... допомагати людям так швидко.'::text,'можеш'::text,'можеш'::text,'можеш'::text,'Респект, ти можеш допомагати людям так швидко.'::text),
